select.foreach:
SELECT
    d.id
FROM
    (
        SELECT
            @ids${idx} AS _ids,
            (
                SELECT
                    @ids${idx} := GROUP_CONCAT(id)
                FROM
                    forum_comment
                WHERE FIND_IN_SET(belong_comment_id, @ids${idx})
            ) AS cids,
            @l${idx} := @l${idx} + 1 AS level
        FROM
            forum_comment,
            (
                SELECT
                    @ids${idx} := #{id},
                    @l${idx} := 0
            ) b
        WHERE @ids${idx} IS NOT NULL
    ) i,
    forum_comment d
WHERE FIND_IN_SET(d.id, i._ids)

mapper.select:
SELECT a.id, a.forum_id forumId, a.content, a.comment_id commentId, a.belong_comment_id belongCommentId, a.reply_id replyId, a.comment_time commentTime, a.create_id createId, CONVERT(a.create_time, char) createTime, a.last_update_id lastUpdateId, CONVERT(a.last_update_time, char) lastUpdateTime FROM forum_comment a
#{id}
ORDER BY a.create_time DESC
